"""Build an offline gallery from actual synthetic browser screenshots."""
import argparse,base64,html
from pathlib import Path
parser=argparse.ArgumentParser();parser.add_argument('--output',required=True);parser.add_argument('--version',default='5.2.0');args=parser.parse_args()
root=Path(__file__).resolve().parents[1]
screens=[('today-web-demo.png','Today'),('reports-web-demo.png','Reports, PDF review & exports'),('settings-web-demo.png','Connections & settings'),('reports-small-web-demo.png','Smaller workstation window')]
buttons=''.join(f'<button onclick="show({i})">{html.escape(label)}</button>' for i,(name,label) in enumerate(screens))
figures=''.join(f'<figure id="screen{i}" style="display:{"block" if i==0 else "none"}"><figcaption>{html.escape(label)} — actual offline interface with synthetic demonstration data</figcaption><img alt="{html.escape(label)}" src="data:image/png;base64,{base64.b64encode((root/"docs/images"/name).read_bytes()).decode()}"></figure>' for i,(name,label) in enumerate(screens))
page='<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>CT QA Manager Pro '+html.escape(args.version)+' preview</title><style>body{font:16px/1.5 Segoe UI,sans-serif;background:#f3f7f6;color:#17353e;max-width:1200px;margin:30px auto;padding:20px}p,figcaption{color:#526d75}nav{display:flex;flex-wrap:wrap;gap:8px;margin:24px 0}button{background:#fff;border:1px solid #80b9ad;color:#174e49;border-radius:8px;padding:12px;cursor:pointer}figure{margin:0}img{width:100%;height:auto;border:1px solid #d6e2df;border-radius:12px;margin-top:12px}</style><h1>CT QA Manager Pro '+html.escape(args.version)+'</h1><p>The original program\'s archive, connections and export tools, with a local HTML interface. These are screenshots, not an interactive program. All demonstration reports are synthetic. This gallery opens without an internet connection.</p><nav>'+buttons+'</nav>'+figures+'<script>function show(n){for(let i=0;i<'+str(len(screens))+';i++)document.getElementById("screen"+i).style.display=i===n?"block":"none"}</script></html>'
Path(args.output).write_text(page,encoding='utf-8')
